$ErrorActionPreference='Stop';Set-Location $PSScriptRoot
if(-not(Get-Command docker -ErrorAction SilentlyContinue)){throw 'Docker is missing. Install Docker Desktop first.'};docker info|Out-Null;if($LASTEXITCODE -ne 0){throw 'Docker daemon is not running. Start Docker Desktop.'};docker compose version|Out-Null;if($LASTEXITCODE -ne 0){throw 'Docker Compose v2 required.'}
'data/market','data/screenshots','data/backups','data/logs','backups','logs'|ForEach-Object{New-Item -ItemType Directory -Force $_|Out-Null};$port=8080;if(Test-Path '.env'){$line=Get-Content .env|Where-Object{$_ -match '^ATLAS_PORT='}|Select-Object -Last 1;if($line){$port=[int]($line -replace '^ATLAS_PORT=','')}};while($true){$l=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Loopback,$port);try{$l.Start();$l.Stop();break}catch{$port++}};Set-Content .env "ATLAS_PORT=$port";docker compose build atlas;if($LASTEXITCODE -ne 0){throw 'Image build failed'};docker compose up -d atlas;if($LASTEXITCODE -ne 0){throw 'Container startup failed'};for($i=0;$i -lt 60;$i++){try{$h=Invoke-RestMethod "http://127.0.0.1:$port/api/health" -TimeoutSec 2;if($h.ok){Write-Host "Ready: http://localhost:$port";exit 0}}catch{};Start-Sleep 2};docker compose logs --tail 100 atlas;throw 'Health check timed out'
